$pageTitle='Support Requests';require_once __DIR__.'/../config/database.php';require_once __DIR__.'/../includes/functions.php';requireAdmin();
if($_SERVER['REQUEST_METHOD']==='POST'){$stmt=$pdo->prepare("UPDATE service_requests SET admin_response=?,status='Answered' WHERE id=?");$stmt->execute([trim($_POST['response']),(int)$_POST['id']]);redirect('/admin/requests.php');}
