?><section class="section"><div class="container"><h1>Customer service requests</h1><?php require __DIR__.'/_nav.php';?><div class="grid"><?php foreach($rows as $r):?><article class="panel card-body"><h2><?=e($r['subject'])?></h2><p><?=e($r['email'])?> · <?=e($r['status'])?></p><p><?=nl2br(e($r['message']))?></p><form method="post"><input type="hidden" name="id" value="<?=(int)$r['id']?>"><textarea name="response" rows="4"><?=e($r['admin_response'])?></textarea><button class="btn btn-primary">Send response</button></form></article><?php endforeach;?></div></div></section><?php require __DIR__.'/../includes/footer.php'; ?>
